"""Provided deterministic experiment/plot runner. Do not edit this file."""
import argparse
import csv
from pathlib import Path
from inference import filter_sequence, predict_steps
from models import get_model, SEQUENCES


def run(output_dir="results"):
    # Import only here so inference, the CLI, and tests need no external library.
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt

    out = Path(output_dir)
    out.mkdir(parents=True, exist_ok=True)
    base = get_model()
    classroom = filter_sequence(base.prior, SEQUENCES["classroom"], base.transition, base.sensor)
    with (out / "classroom.csv").open("w", newline="") as f:
        writer = csv.writer(f)
        writer.writerow(["day", "observation", "p_rain", "p_no_rain"])
        writer.writerows((t, base.symbols[e], *b) for t, (e, b) in enumerate(zip(SEQUENCES["classroom"], classroom), 1))

    comparison_rows = []
    for filename, title, names in [
        ("sensor_comparison.png", "Observation reliability (fixed transition model)", ["reliable", "noisy"]),
        ("transition_comparison.png", "State persistence (fixed observation model)", ["persistent", "weak"]),
    ]:
        fig, axes = plt.subplots(1, 3, figsize=(12, 3.8), sharey=True)
        for ax, seq in zip(axes, ["a", "b", "c"]):
            observations = SEQUENCES[seq]
            for name in names:
                model = get_model(name)
                beliefs = filter_sequence(model.prior, observations, model.transition, model.sensor)
                series = [model.prior[0]] + [b[0] for b in beliefs]
                ax.plot(range(len(series)), series, marker="o", linewidth=1.6, label=name)
                comparison_rows.extend((name, seq.upper(), t, model.symbols[e], *b)
                                       for t, (e, b) in enumerate(zip(observations, beliefs), 1))
            ax.set_title(f"{seq.upper()}: " + " ".join(base.symbols[e] for e in observations))
            ax.set_xlabel("Day (0 = prior)")
            ax.set_ylim(0, 1)
            ax.set_xticks(range(7))
            ax.grid(alpha=.25)
            ax.legend(loc="best", fontsize=8)
        axes[0].set_ylabel("P(Rain | evidence so far)")
        fig.suptitle(title)
        fig.tight_layout(rect=(0, 0, 1, .93))
        fig.savefig(out / filename, dpi=180)
        plt.close(fig)
    with (out / "comparisons.csv").open("w", newline="") as f:
        writer = csv.writer(f)
        writer.writerow(["model", "sequence", "day", "observation", "p_rain", "p_no_rain"])
        writer.writerows(comparison_rows)
    with (out / "future_predictions.csv").open("w", newline="") as f:
        writer = csv.writer(f)
        writer.writerow(["steps_after_day_3", "p_rain", "p_no_rain"])
        for k in [0, 1, 2, 5, 10]:
            writer.writerow([k, *predict_steps(classroom[-1], base.transition, k)])
    print("Wrote classroom.csv, comparisons.csv, future_predictions.csv,")
    print("sensor_comparison.png and transition_comparison.png to", out.resolve())


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="Generate the required Lab 3 experiments")
    parser.add_argument("--output", default="results")
    run(parser.parse_args().output)
